const cmd = `$d='D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts\\_ov2_cc'
Get-ChildItem $d -Filter *.json | ForEach-Object {
  $j = Get-Content $_.FullName -Raw | ConvertFrom-Json
  Write-Output ("##### " + $j.query + "  (" + $j.rows.Count + ")")
  foreach($r in $j.rows){
    if($r.text.Length -gt 60){
      Write-Output ("  [" + $r.created + "] " + $r.title)
      Write-Output ("      " + $r.text.Substring(0,[Math]::Min(400,$r.text.Length)))
    }
  }
}`;
const r = await tools.pwsh({ description: "Dump CC search results", command: cmd });
console.log(r.kind === 'foreground' ? r.stdout.text : JSON.stringify(r));
